// Custom Cloudflare Worker entry: the Next.js app (built by OpenNext) handles
// web requests, and the hourly cron trigger sends reminder notifications.
// See https://opennext.js.org/cloudflare/howtos/custom-worker

// @ts-ignore — generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { runReminders } from "./src/lib/reminders";

// Re-export anything else the generated worker defines (e.g. Durable Objects).
// @ts-ignore
export * from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      runReminders(env)
        .then((r) => console.log("reminders", JSON.stringify(r)))
        .catch((e) => console.error("reminders failed", e && e.message)),
    );
  },
};
